pub fn remove_known_deleted(&mut self, key: &FileKey, has_baseline: bool) {
    self.record_settlement(key);
    self.entries.remove(key);
    self.unread_keys.remove(key);
    // The baseline copy is HIDDEN, not unhidden: for a remote baseline this set is the
    // only filter, and the deleted file would otherwise resurface as a baseline hit the
    // moment its local entry is gone. Hiding takes EVIDENCE of a baseline copy: a key
    // outside the baseline has nothing to hide, and under a dead root the parasitic
    // hiding would be unremovable and inflate the deleted-files stat forever.
    if has_baseline {
        self.hidden_paths.insert(key.clone());
    } else {
        self.hidden_paths.remove(key);
    }
}

/// Apply the in-memory half of a registered-root transition without discarding state that
/// still names the same physical files.
///
/// `affected` is the old content that was removed or rebuilt. `obsolete_baseline` is the
/// subset whose remote baseline copy must stay hidden. `prepared` contains only live local
/// deltas under the new table; local-SQLite callers pass no entries because those files were
/// written to the main store instead. The wholesale fence invalidates every full-tree plan
/// built under the previous table, while per-key settlements for stable files survive.
pub(crate) fn transition_workspace_roots(
    &mut self,
    affected: &HashSet<FileKey>,
    obsolete_baseline: &HashSet<FileKey>,
    prepared: Vec<(FileKey, OverlayFileEntry)>,
) {
    for key in affected {
        self.entries.remove(key);
        self.dirty_paths.remove(key);
        self.dirty_failures.remove(key);
        self.unread_keys.remove(key);
        self.settled_seq.remove(key);
        if obsolete_baseline.contains(key) {
            self.hidden_paths.insert(key.clone());
        } else {
            self.hidden_paths.remove(key);
        }
    }
    for (key, entry) in prepared {
        self.hidden_paths.remove(&key);
        self.entries.insert(key, entry);
    }

    // Unlike `bump_wholesale`, keep settlements of stable keys: only affected keys changed
    // ownership. The shared counter still makes every plan captured before this transition
    // return `Superseded`.
    self.dirty_seq += 1;
    self.wholesale_seq = self.dirty_seq;
}

