/// Atomically replace every persistent carrier affected by a registered-root transition.
///
/// The baseline manifest is intentionally untouched: it belongs to the published remote
/// corpus. Its obsolete keys are represented by tombstones (and by the in-memory hiding
/// applied by the caller). Rebuilt files are inserted without embeddings; the background
/// semantic pass fills the resulting NULL rows after lexical publication.
pub(crate) fn transition_code_files(
    &mut self,
    affected: &[FileKey],
    obsolete_baseline: &HashSet<FileKey>,
    rebuilt: &[PreparedCodeFile],
    write_local_files: bool,
) -> Result<(), SearchError> {
    let tx = self.conn.transaction()?;
    let deleted_at = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
        .to_string();

    for key in affected {
        tx.execute(
            "DELETE FROM chunks_fts WHERE rowid IN (
                 SELECT c.id FROM chunks c
                 JOIN files f ON f.id = c.file_id
                 WHERE f.root_id = ?1 AND f.path = ?2 AND f.collection = 'code'
             )",
            params![key.root_id, key.path],
        )?;
        tx.execute(
            "DELETE FROM files WHERE root_id = ?1 AND path = ?2 AND collection = 'code'",
            params![key.root_id, key.path],
        )?;
        tx.execute(
            "DELETE FROM overlay_chunks_fts WHERE rowid IN (
                 SELECT c.id FROM overlay_chunks c
                 JOIN overlay_files f ON f.id = c.file_id
                 WHERE f.root_id = ?1 AND f.path = ?2 AND f.collection = 'code'
             )",
            params![key.root_id, key.path],
        )?;
        tx.execute(
            "DELETE FROM overlay_files
             WHERE root_id = ?1 AND path = ?2 AND collection = 'code'",
            params![key.root_id, key.path],
        )?;
        tx.execute(
            "DELETE FROM overlay_fingerprint_cache
             WHERE root_id = ?1 AND path = ?2",
            params![key.root_id, key.path],
        )?;
        tx.execute(
            "DELETE FROM context_dirty
             WHERE root_id = ?1 AND path = ?2 AND collection = 'code'",
            params![key.root_id, key.path],
        )?;
        tx.execute(
            "DELETE FROM overlay_tombstones WHERE root_id = ?1 AND path = ?2",
            params![key.root_id, key.path],
        )?;
        if obsolete_baseline.contains(key) {
            tx.execute(
                "INSERT INTO overlay_tombstones (root_id, path, collection, deleted_at)
                 VALUES (?1, ?2, 'code', ?3)
                 ON CONFLICT(root_id, path) DO UPDATE
                 SET collection = 'code', deleted_at = ?3",
                params![key.root_id, key.path, deleted_at],
            )?;
        }
    }

    if write_local_files {
        for file in rebuilt.iter().filter(|file| !file.chunks.is_empty()) {
            Self::reindex_file_in_collection_on(
                &tx,
                &file.key.root_id,
                &file.key.path,
                &file.hash,
                "code",
                &file.chunks,
                None,
                Some(&file.graph_contexts),
            )?;
        }
    }

    tx.commit()?;
    Ok(())
}

