/// Point the engine at a workspace whose only source root is the workspace
/// directory itself. Every file found under it is the configuration's, which
/// is what a caller with no project model to consult can honestly say.
pub fn set_workspace_root(&mut self, workspace_root: impl Into<std::path::PathBuf>) {
    let workspace_root = workspace_root.into();
    let (roots, _) = WorkspaceRoots::build(&workspace_root, &workspace_root, &[]);
    self.set_workspace_roots(roots);
}

pub fn set_workspace_roots(&mut self, roots: WorkspaceRoots) {
    self.workspace_roots = Some(roots);
    if let Ok(mut cache) = self.workspace_overlay_cache.lock() {
        cache.clear();
    }
}

edits.newText:
/// Point the engine at a workspace whose only source root is the workspace
/// directory itself. Every file found under it is the configuration's, which
/// is what a caller with no project model to consult can honestly say.
pub fn set_workspace_root(&mut self, workspace_root: impl Into<std::path::PathBuf>) {
    let workspace_root = workspace_root.into();
    let (roots, _) = WorkspaceRoots::build(&workspace_root, &workspace_root, &[]);
    self.set_workspace_roots(roots);
}

/// Install the complete registered-root table during boot.
///
/// This explicit plural initializer exists so a caller publishing a configuration plus its
/// extensions cannot accidentally go through the singular convenience wrapper and lose the
/// extension key spaces. Live changes use [`Self::workspace_roots_transition_seed`] instead.
pub fn initialize_workspace_roots(
    &mut self,
    roots: WorkspaceRoots,
) -> Result<(), SearchError> {
    if self.workspace_roots.is_some() {
        return Err(SearchError::Index(
            "workspace roots are already initialized; use a live transition".to_owned(),
        ));
    }
    self.workspace_roots = Some(roots);
    self.workspace_roots_epoch = self.workspace_roots_epoch.wrapping_add(1);
    Ok(())
}

/// Compatibility boot setter. New plural callers should use
/// [`Self::initialize_workspace_roots`]; retaining this wrapper keeps one-shot indexers and
/// existing tests source-compatible while the live path has no reason to call it.
pub fn set_workspace_roots(&mut self, roots: WorkspaceRoots) {
    self.workspace_roots = Some(roots);
    self.workspace_roots_epoch = self.workspace_roots_epoch.wrapping_add(1);
    if let Ok(mut cache) = self.workspace_overlay_cache.lock() {
        cache.clear();
    }
}

/// Capture the engine-owned inputs needed to plan a root transition. Callers take this under
/// their outer engine mutex, release it for [`Self::plan_workspace_roots_transition`], then
/// reacquire it for [`Self::apply_workspace_roots_transition`].
pub fn workspace_roots_transition_seed(
    &self,
    new_roots: WorkspaceRoots,
) -> Result<WorkspaceRootsTransitionSeed, SearchError> {
    let old_roots = self.workspace_roots.clone().ok_or_else(|| {
        SearchError::Index("workspace roots must be initialized before a transition".to_owned())
    })?;
    let carriers = self.carrier_keys()?;
    let manifest = self.dispatched_manifest_fingerprints()?.unwrap_or_default();
    Ok(WorkspaceRootsTransitionSeed {
        epoch: self.workspace_roots_epoch,
        old_roots,
        new_roots,
        known_keys: carriers.all_keys(),
        manifest,
        serves_external_baseline: self.serves_external_baseline,
        baseline_hash_mode: self.workspace_baseline_hash_mode,
        graph_context_provider: self.graph_context_provider.clone(),
    })
}

/// Walk, read and chunk the new registered universe without borrowing a live engine.
pub fn plan_workspace_roots_transition(
    seed: WorkspaceRootsTransitionSeed,
) -> Result<WorkspaceRootsTransitionPlan, SearchError> {
    if seed.old_roots.layout_eq(&seed.new_roots) {
        return Ok(WorkspaceRootsTransitionPlan {
            epoch: seed.epoch,
            old_roots: seed.old_roots,
            new_roots: seed.new_roots,
            stable: seed.known_keys.len(),
            rebuilt: 0,
            added: 0,
            obsolete: 0,
            affected: Vec::new(),
            obsolete_baseline: HashSet::new(),
            prepared: Vec::new(),
            validation: Vec::new(),
            unchanged: true,
            serves_external_baseline: seed.serves_external_baseline,
        });
    }

    let declared: Vec<PathBuf> =
        seed.new_roots.entries().map(|(_, path)| path.to_path_buf()).collect();
    let scan = project_model::SourceSet::scan(&declared);
    if !scan.clean() {
        return Err(SearchError::Index(format!(
            "workspace roots transition scan is incomplete: unreadable={}, canonical_fallbacks={}",
            scan.unreadable, scan.canonical_fallbacks
        )));
    }
    let files = Self::files_from_scan(&seed.new_roots, &scan);
    let mut present = HashSet::new();
    let mut physical = HashMap::new();
    let mut validation = Vec::with_capacity(files.len());
    let mut contents = HashMap::new();
    for (key, path) in files {
        let bytes = std::fs::read(&path).map_err(|error| {
            SearchError::Index(format!(
                "failed to read workspace file during roots transition {}: {error}",
                path.display()
            ))
        })?;
        let canonical = std::fs::canonicalize(&path).unwrap_or_else(|_| path.clone());
        let content_hash = blake3::hash(&bytes).as_bytes().to_vec();
        present.insert(key.clone());
        physical.insert(key.clone(), canonical.clone());
        contents.insert(key.clone(), (path.clone(), bytes));
        validation.push(TransitionValidationFile {
            key,
            abs_path: path,
            canonical,
            content_hash,
        });
    }

    let stable_keys: HashSet<FileKey> = present
        .iter()
        .filter(|key| {
            seed.known_keys.contains(*key)
                && seed.old_roots.resolve(key).is_some_and(|old| {
                    let old = std::fs::canonicalize(&old).unwrap_or(old);
                    physical.get(*key).is_some_and(|new| *new == old)
                })
        })
        .cloned()
        .collect();
    let rebuild_keys: HashSet<FileKey> = present
        .iter()
        .filter(|key| seed.known_keys.contains(*key) && !stable_keys.contains(*key))
        .cloned()
        .collect();
    let added_keys: HashSet<FileKey> =
        present.difference(&seed.known_keys).cloned().collect();
    let obsolete_keys: HashSet<FileKey> =
        seed.known_keys.difference(&present).cloned().collect();
    let mut affected: Vec<FileKey> =
        obsolete_keys.union(&rebuild_keys).cloned().collect();
    affected.sort();
    let obsolete_baseline: HashSet<FileKey> = obsolete_keys
        .iter()
        .filter(|key| seed.manifest.contains_key(*key))
        .cloned()
        .collect();

    let mut prepare_keys: Vec<FileKey> =
        rebuild_keys.union(&added_keys).cloned().collect();
    prepare_keys.sort();
    let mut prepared = Vec::with_capacity(prepare_keys.len());
    for key in prepare_keys {
        let (path, bytes) = contents
            .remove(&key)
            .expect("every planned live key came from the same source set");
        let content = String::from_utf8(bytes).map_err(|error| {
            SearchError::Index(format!(
                "workspace source is not UTF-8 during roots transition {}: {error}",
                path.display()
            ))
        })?;
        let chunks = Chunker::chunk(&content);
        let graph_contexts: Vec<Option<String>> = chunks
            .iter()
            .map(|chunk| {
                crate::document::indexed_document_for_chunk(
                    &key,
                    chunk,
                    seed.graph_context_provider.as_deref(),
                )
                .graph_context
            })
            .collect();
        let store = PreparedCodeFile {
            key: key.clone(),
            hash: blake3::hash(content.as_bytes()).as_bytes().to_vec(),
            chunks,
            graph_contexts,
        };

        let overlay = if seed.serves_external_baseline
            && seed.manifest.get(&key).is_none_or(|baseline| {
                *baseline != fingerprint_content(&content, &key.path)
            })
        {
            let metadata = std::fs::metadata(&path).map_err(|error| {
                SearchError::Index(format!(
                    "failed to stat workspace file during roots transition {}: {error}",
                    path.display()
                ))
            })?;
            let fingerprint = FileFingerprint {
                len: metadata.len(),
                modified: metadata.modified().ok(),
                canonical: std::fs::canonicalize(&path).unwrap_or_else(|_| path.clone()),
            };
            let file_hash = compute_file_hash(&content, seed.baseline_hash_mode);
            Some(build_overlay_entry(
                &key,
                &content,
                fingerprint,
                file_hash,
                None,
                1,
                &mut HashMap::new(),
                seed.graph_context_provider.as_deref(),
                None,
            )?)
        } else {
            None
        };
        prepared.push(PreparedTransitionFile { store, overlay });
    }

    validation.sort_by(|left, right| left.key.cmp(&right.key));
    Ok(WorkspaceRootsTransitionPlan {
        epoch: seed.epoch,
        old_roots: seed.old_roots,
        new_roots: seed.new_roots,
        stable: stable_keys.len(),
        rebuilt: rebuild_keys.len(),
        added: added_keys.len(),
        obsolete: obsolete_keys.len(),
        affected,
        obsolete_baseline,
        prepared,
        validation,
        unchanged: false,
        serves_external_baseline: seed.serves_external_baseline,
    })
}

/// Publish a planned transition under the caller's outer engine mutex. The root table is
/// assigned last, after the persistent transaction, vector swap and selective cache update.
pub fn apply_workspace_roots_transition(
    &mut self,
    plan: WorkspaceRootsTransitionPlan,
) -> Result<WorkspaceRootsTransitionOutcome, SearchError> {
    if self.workspace_roots_epoch != plan.epoch
        || self
            .workspace_roots
            .as_ref()
            .is_none_or(|roots| !roots.layout_eq(&plan.old_roots))
    {
        return Ok(WorkspaceRootsTransitionOutcome::Superseded);
    }
    if plan.unchanged {
        return Ok(WorkspaceRootsTransitionOutcome::Unchanged);
    }

    let declared: Vec<PathBuf> =
        plan.new_roots.entries().map(|(_, path)| path.to_path_buf()).collect();
    let scan = project_model::SourceSet::scan(&declared);
    if !scan.clean() {
        return Ok(WorkspaceRootsTransitionOutcome::Superseded);
    }
    let validation_files = Self::files_from_scan(&plan.new_roots, &scan);
    if validation_files.len() != plan.validation.len() {
        return Ok(WorkspaceRootsTransitionOutcome::Superseded);
    }
    let expected: HashMap<&FileKey, &TransitionValidationFile> =
        plan.validation.iter().map(|file| (&file.key, file)).collect();
    for (key, path) in validation_files {
        let Some(planned) = expected.get(&key) else {
            return Ok(WorkspaceRootsTransitionOutcome::Superseded);
        };
        let canonical = std::fs::canonicalize(&path).unwrap_or_else(|_| path.clone());
        if canonical != planned.canonical || path != planned.abs_path {
            return Ok(WorkspaceRootsTransitionOutcome::Superseded);
        }
        let bytes = match std::fs::read(&path) {
            Ok(bytes) => bytes,
            Err(_) => return Ok(WorkspaceRootsTransitionOutcome::Superseded),
        };
        if blake3::hash(&bytes).as_bytes() != planned.content_hash.as_slice() {
            return Ok(WorkspaceRootsTransitionOutcome::Superseded);
        }
    }

    let removed_chunk_ids: HashSet<i64> = plan
        .affected
        .iter()
        .map(|key| self.store.chunk_ids_for_file("code", &key.root_id, &key.path))
        .collect::<Result<Vec<_>, _>>()?
        .into_iter()
        .flatten()
        .collect();
    let retained_embeddings: Vec<(i64, Vec<f32>)> = self
        .store
        .load_all_embeddings(self.dim)?
        .into_iter()
        .filter(|(id, _)| !removed_chunk_ids.contains(id))
        .collect();
    let next_index = VectorIndex::build(self.dim, &retained_embeddings)?;
    let mut cache = self.workspace_overlay_cache.lock().map_err(|error| {
        SearchError::Index(format!("workspace overlay cache lock error: {error}"))
    })?;

    let pending_collection_embeddings = !plan.serves_external_baseline
        && self.embedder.is_some()
        && plan.prepared.iter().any(|file| !file.store.chunks.is_empty());
    let pending_overlay_embeddings = plan.serves_external_baseline
        && self.embedder.is_some()
        && plan.prepared.iter().any(|file| file.overlay.is_some());
    let overlay_entries: Vec<(FileKey, OverlayFileEntry)> = plan
        .prepared
        .iter_mut()
        .filter_map(|file| file.overlay.take().map(|entry| (file.store.key.clone(), entry)))
        .collect();
    let rebuilt: Vec<PreparedCodeFile> =
        plan.prepared.into_iter().map(|file| file.store).collect();

    self.store.transition_code_files(
        &plan.affected,
        &plan.obsolete_baseline,
        &rebuilt,
