                && seed.manifest.get(&key).is_none_or(|baseline| {
                    *baseline != fingerprint_content(&content, &key.path)
                })
            {
                let metadata = std::fs::metadata(&path).map_err(|error| {
                    SearchError::Index(format!(
                        "failed to stat workspace file during roots transition {}: {error}",
                        path.display()
                    ))
                })?;
                let fingerprint = FileFingerprint {
                    len: metadata.len(),
                    modified: metadata.modified().ok(),
                    canonical: std::fs::canonicalize(&path).unwrap_or_else(|_| path.clone()),
                };
                let file_hash = compute_file_hash(&content, seed.baseline_hash_mode);
                Some(build_overlay_entry(
                    &key,
                    &content,
                    fingerprint,
                    file_hash,
                    None,
                    1,
                    &mut HashMap::new(),
                    seed.graph_context_provider.as_deref(),
                    None,
                )?)
            } else {
                None
            };
            prepared.push(PreparedTransitionFile { store, overlay });
        }

        validation.sort_by(|left, right| left.key.cmp(&right.key));
        Ok(WorkspaceRootsTransitionPlan {
            epoch: seed.epoch,
            old_roots: seed.old_roots,
            new_roots: seed.new_roots,
            stable: stable_keys.len(),
            rebuilt: rebuild_keys.len(),
            added: added_keys.len(),
            obsolete: obsolete_keys.len(),
            affected,
            obsolete_baseline,
            prepared,
            validation,
            unchanged: false,
            serves_external_baseline: seed.serves_external_baseline,
        })
    }

    /// Publish a planned transition under the caller's outer engine mutex. The root table is
    /// assigned last, after the persistent transaction, vector swap and selective cache update.
    pub fn apply_workspace_roots_transition(
        &mut self,
        plan: WorkspaceRootsTransitionPlan,
    ) -> Result<WorkspaceRootsTransitionOutcome, SearchError> {
        if self.workspace_roots_epoch != plan.epoch
            || self
                .workspace_roots
                .as_ref()
                .is_none_or(|roots| !roots.layout_eq(&plan.old_roots))
        {
            return Ok(WorkspaceRootsTransitionOutcome::Superseded);
        }
        if plan.unchanged {
            return Ok(WorkspaceRootsTransitionOutcome::Unchanged);
        }

        let declared: Vec<PathBuf> =
            plan.new_roots.entries().map(|(_, path)| path.to_path_buf()).collect();
        let scan = project_model::SourceSet::scan(&declared);
        if !scan.clean() {
            return Ok(WorkspaceRootsTransitionOutcome::Superseded);
        }
        let validation_files = Self::files_from_scan(&plan.new_roots, &scan);
        if validation_files.len() != plan.validation.len() {
            return Ok(WorkspaceRootsTransitionOutcome::Superseded);
        }
        let expected: HashMap<&FileKey, &TransitionValidationFile> =
            plan.validation.iter().map(|file| (&file.key, file)).collect();
        for (key, path) in validation_files {
            let Some(planned) = expected.get(&key) else {
                return Ok(WorkspaceRootsTransitionOutcome::Superseded);
            };
            let canonical = std::fs::canonicalize(&path).unwrap_or_else(|_| path.clone());
            if canonical != planned.canonical || path != planned.abs_path {
                return Ok(WorkspaceRootsTransitionOutcome::Superseded);
            }
            let bytes = match std::fs::read(&path) {
                Ok(bytes) => bytes,
                Err(_) => return Ok(WorkspaceRootsTransitionOutcome::Superseded),
            };
            if blake3::hash(&bytes).as_bytes() != planned.content_hash.as_slice() {
                return Ok(WorkspaceRootsTransitionOutcome::Superseded);
            }
        }

        let removed_chunk_ids: HashSet<i64> = plan
            .affected
            .iter()
            .map(|key| self.store.chunk_ids_for_file("code", &key.root_id, &key.path))
            .collect::<Result<Vec<_>, _>>()?
            .into_iter()
            .flatten()
            .collect();
        let retained_embeddings: Vec<(i64, Vec<f32>)> = self
            .store
            .load_all_embeddings(self.dim)?
            .into_iter()
            .filter(|(id, _)| !removed_chunk_ids.contains(id))
            .collect();
        let next_index = VectorIndex::build(self.dim, &retained_embeddings)?;
        let mut cache = self.workspace_overlay_cache.lock().map_err(|error| {
            SearchError::Index(format!("workspace overlay cache lock error: {error}"))
        })?;

        let pending_collection_embeddings = !plan.serves_external_baseline
            && self.embedder.is_some()
            && plan.prepared.iter().any(|file| !file.store.chunks.is_empty());
        let pending_overlay_embeddings = plan.serves_external_baseline
            && self.embedder.is_some()
            && plan.prepared.iter().any(|file| file.overlay.is_some());
        let overlay_entries: Vec<(FileKey, OverlayFileEntry)> = plan
            .prepared
            .iter_mut()
            .filter_map(|file| file.overlay.take().map(|entry| (file.store.key.clone(), entry)))
            .collect();
        let rebuilt: Vec<PreparedCodeFile> =
            plan.prepared.into_iter().map(|file| file.store).collect();

        self.store.transition_code_files(
            &plan.affected,
            &plan.obsolete_baseline,
            &rebuilt,
            !plan.serves_external_baseline,
        )?;
        self.index = next_index;
        cache.transition_workspace_roots(
            &plan.affected.iter().cloned().collect(),
            &plan.obsolete_baseline,
            overlay_entries,
        );
        self.workspace_roots = Some(plan.new_roots);
        self.workspace_roots_epoch = self.workspace_roots_epoch.wrapping_add(1);

        Ok(WorkspaceRootsTransitionOutcome::Applied {
            stable: plan.stable,
            rebuilt: plan.rebuilt,
            added: plan.added,
            obsolete: plan.obsolete,
            pending_collection_embeddings,
            pending_overlay_embeddings,
        })
    }
"
    }
