        let (roots, _) = crate::WorkspaceRoots::build(workspace, workspace, &[]);
        engine.set_workspace_roots(roots);
        engine.prime_workspace_overlay().unwrap();
        let hits = engine.text_search("ЗаЗакрытымКаталогом", 10, Some("code")).unwrap();
