#[test]
fn live_roots_transition_adds_and_removes_a_local_extension() {
    let dir = tempdir().unwrap();
    let workspace = dir.path();
    let configuration = workspace.join("cf");
    let extension = workspace.join("ext-a");
    fs::create_dir_all(&configuration).unwrap();
    fs::create_dir_all(&extension).unwrap();
    fs::write(configuration.join("M.bsl"), "Процедура Конфигурация()\nКонецПроцедуры")
        .unwrap();
    fs::write(extension.join("M.bsl"), "Процедура Расширение()\nКонецПроцедуры").unwrap();

    let mut engine = SearchEngine::fts_only(&workspace.join("search.db")).unwrap();
    let configuration_only = crate::WorkspaceRoots::build(workspace, &configuration, &[]).0;
    engine.initialize_workspace_roots(configuration_only).unwrap();
    engine.index_directory_fts(&configuration).unwrap();

    let both = crate::WorkspaceRoots::build(
        workspace,
        &configuration,
        std::slice::from_ref(&extension),
    )
    .0;
    assert_eq!(
        apply_roots(&mut engine, both),
        super::WorkspaceRootsTransitionOutcome::Applied {
            stable: 1,
            rebuilt: 0,
            added: 1,
            obsolete: 0,
            pending_collection_embeddings: false,
            pending_overlay_embeddings: false,
        }
    );
    let hits = engine.text_search("Расширение", 10, Some("code")).unwrap();
    assert_eq!(hits.first().map(|hit| hit.root_id.as_str()), Some("ext-a"));
    assert_eq!(engine.text_search("Конфигурация", 10, Some("code")).unwrap().len(), 1);

    let configuration_only = crate::WorkspaceRoots::build(workspace, &configuration, &[]).0;
    assert!(matches!(
        apply_roots(&mut engine, configuration_only),
        super::WorkspaceRootsTransitionOutcome::Applied { obsolete: 1, .. }
    ));
    assert!(engine.text_search("Расширение", 10, Some("code")).unwrap().is_empty());
    assert_eq!(engine.text_search("Конфигурация", 10, Some("code")).unwrap().len(), 1);
}

#[test]
fn live_roots_transition_rebuilds_a_reassigned_configuration_key() {
    let dir = tempdir().unwrap();
    let workspace = dir.path();
    let old_configuration = workspace.join("cf-old");
    let new_configuration = workspace.join("cf-new");
    fs::create_dir_all(&old_configuration).unwrap();
    fs::create_dir_all(&new_configuration).unwrap();
    fs::write(old_configuration.join("M.bsl"), "Процедура СтарыйВладелец()\nКонецПроцедуры")
        .unwrap();
    fs::write(new_configuration.join("M.bsl"), "Процедура НовыйВладелец()\nКонецПроцедуры")
        .unwrap();

    let mut engine = SearchEngine::fts_only(&workspace.join("search.db")).unwrap();
    let old = crate::WorkspaceRoots::build(workspace, &old_configuration, &[]).0;
    engine.initialize_workspace_roots(old).unwrap();
    engine.index_directory_fts(&old_configuration).unwrap();

    let new = crate::WorkspaceRoots::build(workspace, &new_configuration, &[]).0;
    assert!(matches!(
        apply_roots(&mut engine, new),
        super::WorkspaceRootsTransitionOutcome::Applied {
            rebuilt: 1,
            added: 0,
            obsolete: 0,
            ..
        }
    ));
    assert!(engine.text_search("СтарыйВладелец", 10, Some("code")).unwrap().is_empty());
    assert_eq!(engine.text_search("НовыйВладелец", 10, Some("code")).unwrap().len(), 1);
}

#[test]
fn live_roots_transition_rejects_a_plan_when_a_new_file_appears() {
    let dir = tempdir().unwrap();
    let workspace = dir.path();
    let configuration = workspace.join("cf");
    let extension = workspace.join("ext");
    fs::create_dir_all(&configuration).unwrap();
    fs::create_dir_all(&extension).unwrap();
    fs::write(configuration.join("Stable.bsl"), "Процедура Стабильная()\nКонецПроцедуры")
        .unwrap();
    fs::write(extension.join("A.bsl"), "Процедура Первая()\nКонецПроцедуры").unwrap();

    let mut engine = SearchEngine::fts_only(&workspace.join("search.db")).unwrap();
    let old = crate::WorkspaceRoots::build(workspace, &configuration, &[]).0;
    engine.initialize_workspace_roots(old).unwrap();
    engine.index_directory_fts(&configuration).unwrap();
    let next = crate::WorkspaceRoots::build(
        workspace,
        &configuration,
        std::slice::from_ref(&extension),
    )
    .0;
    let seed = engine.workspace_roots_transition_seed(next.clone()).unwrap();
    let plan = SearchEngine::plan_workspace_roots_transition(seed).unwrap();
    fs::write(extension.join("B.bsl"), "Процедура Вторая()\nКонецПроцедуры").unwrap();

    assert_eq!(
        engine.apply_workspace_roots_transition(plan).unwrap(),
        super::WorkspaceRootsTransitionOutcome::Superseded
    );
    assert!(!engine.workspace_roots().unwrap().contains_id("ext"));
    assert_eq!(engine.text_search("Стабильная", 10, Some("code")).unwrap().len(), 1);
    assert!(engine.text_search("Первая", 10, Some("code")).unwrap().is_empty());

    assert!(matches!(
        apply_roots(&mut engine, next),
        super::WorkspaceRootsTransitionOutcome::Applied { added: 2, .. }
    ));
    assert_eq!(engine.text_search("Первая", 10, Some("code")).unwrap().len(), 1);
    assert_eq!(engine.text_search("Вторая", 10, Some("code")).unwrap().len(), 1);
}

#[test]
fn live_roots_transition_keeps_old_state_after_an_incomplete_scan() {
    let dir = tempdir().unwrap();
    let workspace = dir.path();
    let configuration = workspace.join("cf");
    fs::create_dir_all(&configuration).unwrap();
    fs::write(configuration.join("M.bsl"), "Процедура Старая()\nКонецПроцедуры").unwrap();

    let mut engine = SearchEngine::fts_only(&workspace.join("search.db")).unwrap();
    let old = crate::WorkspaceRoots::build(workspace, &configuration, &[]).0;
    engine.initialize_workspace_roots(old).unwrap();
    engine.index_directory_fts(&configuration).unwrap();
    let missing = workspace.join("missing-extension");
    let next = crate::WorkspaceRoots::build(workspace, &configuration, &[missing]).0;
    let seed = engine.workspace_roots_transition_seed(next).unwrap();
    assert!(SearchEngine::plan_workspace_roots_transition(seed).is_err());
    assert_eq!(engine.text_search("Старая", 10, Some("code")).unwrap().len(), 1);
    assert_eq!(engine.workspace_roots().unwrap().ids().count(), 1);
}

#[test]
fn remote_overlay_transition_preserves_stable_entries_and_tombstones_removed_roots() {
    let dir = tempdir().unwrap();
    let workspace = dir.path();
    let configuration = workspace.join("cf");
    let extension = workspace.join("ext");
    fs::create_dir_all(&configuration).unwrap();
    fs::create_dir_all(&extension).unwrap();
    let configuration_text = "Процедура ЛокальнаяКонфигурация()\nКонецПроцедуры";
    let extension_text = "Процедура ЛокальноеРасширение()\nКонецПроцедуры";
    fs::write(configuration.join("M.bsl"), configuration_text).unwrap();
    fs::write(extension.join("M.bsl"), extension_text).unwrap();

    let mut engine = SearchEngine::fts_only(&workspace.join("search.db")).unwrap();
    let both = crate::WorkspaceRoots::build(
        workspace,
        &configuration,
        std::slice::from_ref(&extension),
    )
    .0;
    engine.initialize_workspace_roots(both).unwrap();
    engine
        .store()
        .save_baseline_manifest(&crate::WorkspaceBaselineManifest {
            snapshot_id: "snap".to_owned(),
            snapshot_fingerprint: Some("fp".to_owned()),
            files: vec![
                crate::BaselineManifestFile {
                    root_id: crate::CONFIGURATION_ROOT_ID.to_owned(),
                    collection: "code".to_owned(),
                    path: "M.bsl".to_owned(),
                    file_fingerprint: "remote-configuration".to_owned(),
                    document_count: 1,
                    file_object_id: "configuration".to_owned(),
                },
                crate::BaselineManifestFile {
                    root_id: "ext".to_owned(),
                    collection: "code".to_owned(),
                    path: "M.bsl".to_owned(),
                    file_fingerprint: "remote-extension".to_owned(),
                    document_count: 1,
                    file_object_id: "extension".to_owned(),
                },
            ],
        })
        .unwrap();
    engine.set_serves_external_baseline(true).unwrap();
    engine.prime_workspace_overlay().unwrap();
    assert_eq!(engine.workspace_overlay_lexical_hits("ЛокальнаяКонфигурация", 10).unwrap().0.len(), 1);

    let configuration_only = crate::WorkspaceRoots::build(workspace, &configuration, &[]).0;
    assert!(matches!(
        apply_roots(&mut engine, configuration_only),
        super::WorkspaceRootsTransitionOutcome::Applied { obsolete: 1, .. }
    ));
    assert_eq!(engine.workspace_overlay_lexical_hits("ЛокальнаяКонфигурация", 10).unwrap().0.len(), 1);
    assert!(engine.workspace_overlay_lexical_hits("ЛокальноеРасширение", 10).unwrap().0.is_empty());
    let extension_key = FileKey::new("ext", "M.bsl");
    assert!(engine.store().overlay_tombstone_paths("code").unwrap().contains(&extension_key));

    let both = crate::WorkspaceRoots::build(
        workspace,
        &configuration,
        std::slice::from_ref(&extension),
    )
    .0;
    assert!(matches!(
        apply_roots(&mut engine, both),
        super::WorkspaceRootsTransitionOutcome::Applied { rebuilt: 1, .. }
    ));
    assert!(!engine.store().overlay_tombstone_paths("code").unwrap().contains(&extension_key));
    assert_eq!(engine.workspace_overlay_lexical_hits("ЛокальноеРасширение", 10).unwrap().0.len(), 1);
}

#[test]
fn live_roots_transition_supersedes_an_old_whole_tree_overlay_plan() {
    let dir = tempdir().unwrap();
    let workspace = dir.path();
    let configuration = workspace.join("cf");
    let extension = workspace.join("ext");
    fs::create_dir_all(&configuration).unwrap();
    fs::create_dir_all(&extension).unwrap();
    fs::write(configuration.join("M.bsl"), "Процедура Старая()\nКонецПроцедуры").unwrap();
    fs::write(extension.join("M.bsl"), "Процедура Новая()\nКонецПроцедуры").unwrap();

    let mut engine = SearchEngine::fts_only(&workspace.join("search.db")).unwrap();
    let old = crate::WorkspaceRoots::build(workspace, &configuration, &[]).0;
    engine.initialize_workspace_roots(old.clone()).unwrap();
    engine.set_serves_external_baseline(true).unwrap();
    let baseline = engine.workspace_overlay_publication_baseline().unwrap();
    let stale = crate::workspace_overlay::WorkspaceOverlayCache::plan_full_refresh_from_manifest(
        &HashMap::new(),
        &old,
        engine.store(),
        &HashMap::new(),
        None,
        baseline.distrusted(),
    )
    .unwrap();

    let next = crate::WorkspaceRoots::build(
        workspace,
        &configuration,
        std::slice::from_ref(&extension),
    )
    .0;
    assert!(matches!(
        apply_roots(&mut engine, next),
        super::WorkspaceRootsTransitionOutcome::Applied { .. }
    ));
    assert_eq!(
        engine.publish_workspace_overlay(stale, HashMap::new(), &baseline).unwrap(),
        crate::workspace_overlay::PublishOutcome::Superseded
    );
}

